<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {supabase} from '@/lib/supabase'
const from=ref(new Date(new Date().getFullYear(),new Date().getMonth(),1).toISOString().slice(0,10)),to=ref(new Date().toISOString().slice(0,10))
const sales=ref<any[]>([]),expenses=ref<any[]>([]),loading=ref(false),error=ref('')
const revenue=computed(()=>sales.value.reduce((s,x)=>s+Number(x.total||0),0))
const expenseTotal=computed(()=>expenses.value.reduce((s,x)=>s+Number(x.amount||0),0))
async function load(){if(from.value>to.value){error.value='Start date must be on or before end date.';return}loading.value=true;error.value='';const start=from.value+'T00:00:00';const end=new Date(to.value+'T00:00:00');end.setDate(end.getDate()+1);const [s,e]=await Promise.all([supabase.from('sales').select('id,sale_number,total,subtotal,discount,tax,amount_paid,balance,payment_method,payment_status,created_at').gte('created_at',start).lt('created_at',end.toISOString()).order('created_at',{ascending:false}),supabase.from('expenses').select('id,expense_number,description,amount,expense_date,payment_method').gte('expense_date',start).lt('expense_date',end.toISOString()).order('expense_date',{ascending:false})]);if(s.error||e.error)error.value=s.error?.message??e.error?.message??'Unable to load reports';sales.value=s.data??[];expenses.value=e.data??[];loading.value=false}onMounted(load)
</script>
<template><section class="page-wrap"><div class="page-heading"><div><h1>Reports</h1><p>Sales and expenses for a selected period. Profit is not calculated from unavailable cost-of-goods data.</p></div><button class="btn" @click="load">Refresh report</button></div>
<div class="toolbar"><label>From <input v-model="from" type="date" class="control"></label><label>To <input v-model="to" type="date" class="control"></label></div><p v-if="error" class="alert">{{error}}</p><p v-if="loading" class="empty">Loading report…</p><template v-else><div class="stats-grid"><article class="stat"><span>Transactions</span><strong>{{sales.length}}</strong></article><article class="stat"><span>Sales revenue</span><strong>UGX {{revenue.toLocaleString()}}</strong></article><article class="stat"><span>Amount collected</span><strong>UGX {{sales.reduce((s,x)=>s+Number(x.amount_paid||0),0).toLocaleString()}}</strong></article><article class="stat"><span>Outstanding customer balances</span><strong>UGX {{sales.reduce((s,x)=>s+Number(x.balance||0),0).toLocaleString()}}</strong></article><article class="stat"><span>Expenses</span><strong>UGX {{expenseTotal.toLocaleString()}}</strong></article></div>
<div class="panel mt"><h2>Sales detail</h2><div class="table-scroll"><table><thead><tr><th>Sale number</th><th>Date</th><th>Payment</th><th>Status</th><th>Total</th><th>Collected</th><th>Balance</th></tr></thead><tbody><tr v-for="s in sales" :key="s.id"><td>{{s.sale_number}}</td><td>{{new Date(s.created_at).toLocaleString()}}</td><td>{{s.payment_method}}</td><td>{{s.payment_status}}</td><td>UGX {{Number(s.total).toLocaleString()}}</td><td>UGX {{Number(s.amount_paid).toLocaleString()}}</td><td>UGX {{Number(s.balance).toLocaleString()}}</td></tr><tr v-if="!sales.length"><td colspan="7" class="empty">No sales in this period.</td></tr></tbody></table></div></div>
<div class="panel mt"><h2>Expense detail</h2><div class="table-scroll"><table><thead><tr><th>Expense number</th><th>Description</th><th>Date</th><th>Method</th><th>Amount</th></tr></thead><tbody><tr v-for="e in expenses" :key="e.id"><td>{{e.expense_number}}</td><td>{{e.description}}</td><td>{{new Date(e.expense_date).toLocaleString()}}</td><td>{{e.payment_method}}</td><td>UGX {{Number(e.amount).toLocaleString()}}</td></tr><tr v-if="!expenses.length"><td colspan="5" class="empty">No expenses in this period.</td></tr></tbody></table></div></div></template></section></template>